/** Products that are deliberately out of stock, to exercise the empty/disabled states. */
const OUT_OF_STOCK_TITLES = new Set(['Aurexa Studio Book 16 (1 TB)', 'Lumina Volume Mascara']);

let autoId = 0;

/**
 * Expands a shorthand catalogue entry into a full product record.
 * @param {object} entry raw entry from CATALOGUE
 * @param {string} category owning category name
 */
function normalise(entry, category) {
  autoId += 1;
  const slug = slugify(entry.t);
  const stock = OUT_OF_STOCK_TITLES.has(entry.t) ? 0 : entry.stock;
  const discount = entry.mrp > entry.price
    ? Math.round(((entry.mrp - entry.price) / entry.mrp) * 100)
    : 0;

  // Four gallery images per product, keyed off the slug so they stay stable.
  const images = [1, 2, 3, 4].map((n) => `https://picsum.photos/seed/shopnest-${slug}-${n}/900/900`);

  const product = {
    id: autoId,
    slug,
    title: entry.t,
    brand: entry.b,
    category,
    subcategory: entry.sub,
    price: entry.price,
    originalPrice: entry.mrp,
    discount,
    rating: entry.rating,
    reviewCount: entry.rc,
    stock,
    images,
    thumbnail: images[0],
    description: entry.desc,
    highlights: entry.hl,
    specifications: entry.spec,
    tags: entry.tags ?? [],
    isNew: Boolean(entry.isNew),
    isBestSeller: Boolean(entry.best),
    isFeatured: Boolean(entry.feat),
    deliveryDays: entry.delivery ?? 3,
    returnPolicy: entry.returns ?? '7-day easy returns',
    warranty: entry.warranty ?? (category === 'Electronics' ? '1 year manufacturer warranty' : null),
    addedAt: new Date(2026, 0, 1 + (autoId % 250)).toISOString(),
  };

  // Optional fields are only attached when they make sense for the product,
  // so records are intentionally not uniform in shape.
  if (entry.colors) product.colors = entry.colors;
  if (entry.sizes) product.sizes = entry.sizes;
  if (entry.material) product.material = entry.material;
  if (entry.box) product.boxContents = entry.box;
  if (entry.expiry) product.expiry = entry.expiry;

  return product;
}

/** The flat catalogue used by every service and page. */
export const products = Object.entries(CATALOGUE).flatMap(([category, entries]) =>
  entries.map((entry) => normalise(entry, category)),
);

/** Fast lookup maps - avoids repeated O(n) scans in hot paths. */
export const productById = new Map(products.map((p) => [p.id, p]));
export const productBySlug = new Map(products.map((p) => [p.slug, p]));

/** Every distinct brand, alphabetised, for the filter sidebar. */
export const brands = [...new Set(products.map((p) => p.brand))].sort();

/** Colour and size facets, derived rather than hand-maintained. */
export const allColors = [...new Set(products.flatMap((p) => p.colors ?? []))].sort();
export const allSizes = [...new Set(products.flatMap((p) => p.sizes ?? []))];
export const allMaterials = [...new Set(products.map((p) => p.material).filter(Boolean))].sort();

export const priceBounds = {
  min: Math.min(...products.map((p) => p.price)),
  max: Math.max(...products.map((p) => p.price)),
};

/** Brand cards for the homepage showcase. */
export const brandShowcase = brands.map((name, i) => ({
  name,
  productCount: products.filter((p) => p.brand === name).length,
  logo: `https://picsum.photos/seed/shopnest-brand-${slugify(name)}/220/120`,
  since: 1998 + ((i * 3) % 24),
}));

export function getProductById(id) {
  return productById.get(Number(id)) || null;
}

export default products;
